  pres.title = "1,001 Real-World Gen AI Use Cases from Google Cloud Customers";

  // Pre-render all icons
  const icons = {};
  const iconMap = {
    robot: [FaRobot, C.accent],
    user: [FaUserTie, C.accent],
    paint: [FaPaintBrush, C.accentYellow],
    code: [FaCode, C.accentGreen],
    database: [FaDatabase, C.accentRed],
    shield: [FaShieldAlt, C.midGray],
    comments: [FaComments, "#" + C.accent],
    users: [FaUsers, "#" + C.accentGreen],
    rocket: [FaRocket, "#" + C.accentYellow],
    chart: [FaChartLine, "#" + C.accent],
    car: [FaCar, "#" + C.white],
    building: [FaBuilding, "#" + C.midGray],
    university: [FaUniversity, "#" + C.midGray],
    hospital: [FaHospital, "#" + C.midGray],
    plane: [FaPlane, "#" + C.midGray],
    industry: [FaIndustry, "#" + C.midGray],
    gamepad: [FaGamepad, "#" + C.midGray],
    landmark: [FaLandmark, "#" + C.midGray],
    cart: [FaShoppingCart, "#" + C.midGray],
    chip: [FaMicrochip, "#" + C.midGray],
    satellite: [FaSatelliteDish, "#" + C.midGray],
    bullseye: [FaBullseye, "#" + C.accentRed],
    check: [FaCheckCircle, "#" + C.accentGreen],
    clock: [FaClock, "#" + C.accentYellow],
    arrow: [FaArrowRight, "#" + C.accent],
    lightbulb: [FaLightbulb, "#" + C.accentYellow],
    trophy: [FaTrophy, "#" + C.accentYellow],
    bolt: [FaBolt, "#" + C.accentYellow],
    star: [FaStar, "#" + C.accentYellow],
  };

  for (const [key, [Component, color]] of Object.entries(iconMap)) {
    icons[key] = await iconToBase64Png(Component, color);
