      align: "left", margin: 0
    });
  }

  // ========== SLIDE 2: Growth Trajectory ==========
  {
    const slide = pres.addSlide();
    slide.background = { color: C.offWhite };
    addTopAccent(slide);

    slide.addText("From 101 to 1,001: Gen AI Adoption Grew 10× in 18 Months", {
