        x: kx + 0.25, y: ky + 0.12, w: 2.2, h: 0.55,
        fontSize: 36, fontFace: FONT_TITLE, color: kpi.color,
        bold: true, align: "left", margin: 0
      });

      // Label
      slide.addText(kpi.label.toUpperCase(), {
        x: kx + 0.25, y: ky + 0.65, w: 3.0, h: 0.25,
        fontSize: 10, fontFace: FONT_BODY, color: C.textMuted,
        bold: true, align: "left", charSpacing: 2, margin: 0
      });

      // Company name
      slide.addText(kpi.company, {
        x: kx + 0.25, y: ky + 0.95, w: 3.8, h: 0.25,
        fontSize: 12, fontFace: FONT_BODY, color: C.white,
        bold: true, align: "left", margin: 0
      });

      // Description
      slide.addText(kpi.desc, {
        x: kx + 0.25, y: ky + 1.2, w: 3.8, h: 0.45,
        fontSize: 9, fontFace: FONT_BODY, color: C.textMuted,
        align: "left", margin: 0
      });
    });
  }

  // ========== SLIDE 6: Cross-Industry Patterns ==========
  {
    const slide = pres.addSlide();
    slide.background = { color: C.offWhite };
    addTopAccent(slide);

    slide.addText("Common Patterns: Customer Assistants, Employee Productivity, and Creative Scale", {
      x: 0.6, y: 0.25, w: 8.8, h: 0.6,
      fontSize: 22, fontFace: FONT_TITLE, color: C.navy,
      bold: true, align: "left", margin: 0
    });

    // Three pattern columns
    const patterns = [
      {
        icon: icons.comments,
        title: "Conversational\nCustomer Agents",
        tagline: "Most visible entry point",
        color: C.accent,
        companies: "Mercedes-Benz  •  GM OnStar\nVolkswagen  •  LUXGEN\nCommerzbank  •  Mercari",
        desc: "AI-powered virtual assistants handle customer queries, reduce wait times, and lower human agent workloads across automotive, financial services, and retail.",
      },
      {
        icon: icons.users,
        title: "Employee\nProductivity Agents",
        tagline: "Broadest category",
        color: C.accentGreen,
        companies: "Uber  •  Rivian  •  Geotab\nOxa  •  Toyota",
        desc: "Gemini for Workspace summarizes documents, accelerates research, drafts content, reviews legal documents, and filters data across departments from HR to engineering.",
      },
      {
        icon: icons.rocket,
        title: "Creative &\nScale Agents",
        tagline: "Fastest-growing frontier",
        color: C.accentYellow,
        companies: "Virgin Voyages  •  PODS\nFigma",
        desc: "Hyper-personalized video campaigns, real-time adaptive billboards, and instant brand-approved asset generation move gen AI from text into multimodal creative production.",
      },
    ];

    patterns.forEach((p, i) => {
      const px = 0.5 + i * 3.15;
      const cardW = 2.9;

      // Card background
      slide.addShape(pres.shapes.RECTANGLE, {
        x: px, y: 1.1, w: cardW, h: 4.15,
        fill: { color: C.white },
        shadow: { type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.08 }
      });

      // Top accent
      slide.addShape(pres.shapes.RECTANGLE, {
        x: px, y: 1.1, w: cardW, h: 0.05,
        fill: { color: p.color }
      });

      // Icon in colored circle
      slide.addShape(pres.shapes.OVAL, {
        x: px + 0.2, y: 1.4, w: 0.55, h: 0.55,
        fill: { color: p.color, transparency: 85 }
      });
      slide.addImage({
        data: p.icon,
        x: px + 0.33, y: 1.53, w: 0.3, h: 0.3
      });

      // Title
      slide.addText(p.title, {
        x: px + 0.2, y: 2.05, w: cardW - 0.4, h: 0.6,
        fontSize: 15, fontFace: FONT_BODY, color: C.navy,
        bold: true, align: "left", margin: 0
      });

      // Tagline
      slide.addShape(pres.shapes.RECTANGLE, {
        x: px + 0.2, y: 2.7, w: 1.8, h: 0.28,
        fill: { color: p.color, transparency: 85 },
      });
      slide.addText(p.tagline, {
        x: px + 0.3, y: 2.7, w: 1.7, h: 0.28,
        fontSize: 9, fontFace: FONT_BODY, color: p.color,
        bold: true, align: "left", valign: "middle", margin: 0
      });

      // Companies
      slide.addText("KEY PLAYERS", {
        x: px + 0.2, y: 3.15, w: cardW - 0.4, h: 0.22,
        fontSize: 8, fontFace: FONT_BODY, color: C.textMuted,
        bold: true, charSpacing: 2, align: "left", margin: 0
      });
      slide.addText(p.companies, {
        x: px + 0.2, y: 3.37, w: cardW - 0.4, h: 0.6,
        fontSize: 10, fontFace: FONT_BODY, color: C.navy,
        bold: true, align: "left", margin: 0
      });

      // Description
      slide.addText(p.desc, {
        x: px + 0.2, y: 4.1, w: cardW - 0.4, h: 1.0,
        fontSize: 10, fontFace: FONT_BODY, color: C.textMuted,
        align: "left", margin: 0
      });
    });
  }

  // ========== SLIDE 7: Strategic Takeaways ==========
  {
    const slide = pres.addSlide();
    slide.background = { color: C.darkNavy };

    // Decorative element
    slide.addShape(pres.shapes.OVAL, {
      x: 8, y: 3.5, w: 3.5, h: 3.5,
      fill: { color: C.accent, transparency: 92 }
    });

    slide.addText("Takeaways: Where to Start and What to Expect from Enterprise Gen AI", {
      x: 0.6, y: 0.3, w: 8.8, h: 0.6,
      fontSize: 24, fontFace: FONT_TITLE, color: C.white,
      bold: true, align: "left", margin: 0
    });

    const takeaways = [
      {
        num: "01",
        title: "Gen AI Is Production-Ready Across All Major Industries",
        desc: "1,001 real-world deployments across 11 industries prove that gen AI has moved far beyond proof-of-concept into daily enterprise operations.",
        color: C.accent,
      },
      {
        num: "02",
        title: "Customer & Employee Agents Are the Most Common Entry Points",
        desc: "Conversational assistants and workplace productivity tools are the most deployed patterns — start here for proven, lower-risk adoption.",
        color: C.accentGreen,
      },
      {
        num: "03",
        title: "Measurable ROI Is Achievable Within Months",
        desc: "Organizations report 500% ROI, 30% workload reduction, and 10,000+ hours saved — these are production results, not projections.",
        color: C.accentYellow,
      },
      {
        num: "04",
        title: "Creative & Code Agents Are Emerging Fast",
        desc: "From hyper-personalized video campaigns to AI-powered code assistants, the frontier is expanding rapidly into multimodal creative and developer productivity.",
        color: C.accentRed,
      },
      {
        num: "05",
        title: "Early Movers Gain Compounding Advantages",
        desc: "With 10× growth in 18 months and still accelerating, organizations that act now build institutional AI capability that compounds over time.",
        color: "9B59B6",
      },
    ];

    takeaways.forEach((t, i) => {
      const ty = 1.15 + i * 0.85;

      // Number badge
      slide.addShape(pres.shapes.RECTANGLE, {
        x: 0.6, y: ty, w: 0.45, h: 0.45,
        fill: { color: t.color },
      });
      slide.addText(t.num, {
        x: 0.6, y: ty, w: 0.45, h: 0.45,
        fontSize: 16, fontFace: FONT_TITLE, color: C.white,
        bold: true, align: "center", valign: "middle", margin: 0
      });

      // Title
      slide.addText(t.title, {
        x: 1.2, y: ty, w: 8.0, h: 0.3,
        fontSize: 14, fontFace: FONT_BODY, color: C.white,
        bold: true, align: "left", valign: "middle", margin: 0
      });

      // Description
      slide.addText(t.desc, {
        x: 1.2, y: ty + 0.32, w: 7.5, h: 0.4,
        fontSize: 10, fontFace: FONT_BODY, color: C.textMuted,
        align: "left", margin: 0
      });
    });

    // Source footer
    slide.addText("Source: Google Cloud Blog — \"1,001 real-world gen AI use cases from the world's leading organizations,\" October 2025", {
      x: 0.6, y: 5.2, w: 8.5, h: 0.25,
      fontSize: 9, fontFace: FONT_BODY, color: C.textMuted,
      align: "left", margin: 0
    });
  }

  // Write file
  await pres.writeFile({ fileName: "/app/output/final_deck.pptx" });
  console.log("Presentation saved to /app/output/final_deck.pptx");
}

main().catch(err => { console.error(err); process.exit(1); });

