  contextItems.forEach((item, i) => {
    const bx = 0.6 + i * 3.1;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: bx, y: bxY, w: 2.8, h: 1.15,
      fill: { color: C.white },
      shadow: { type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.08 }
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: bx, y: bxY, w: 2.8, h: 0.05,
      fill: { color: item.color }
    });
    slide.addText(item.title, {
      x: bx + 0.15, y: bxY + 0.15, w: 2.5, h: 0.3,
      fontSize: 13, fontFace: FONT_BODY, color: C.navy,
      bold: true, align: "left", margin: 0
    });
    slide.addText(item.desc, {
      x: bx + 0.15, y: bxY + 0.45, w: 2.5, h: 0.6,
      fontSize: 10, fontFace: FONT_BODY, color: C.textMuted,
      align: "left", margin: 0
    });
  });
}

// ========== SLIDE 3: Taxonomy Grid ==========
{
  const slide = pres.addSlide();
  slide.background = { color: C.navy };
  addTopAccent(slide);

  slide.addText("11 Industries × 6 Agent Types: A Taxonomy of Enterprise Gen AI", {
    x: 0.6, y: 0.25, w: 8.8, h: 0.6,
    fontSize: 24, fontFace: FONT_TITLE, color: C.white,
    bold: true, align: "left", margin: 0
  });
  slide.addText("1,001 use cases organized into a structured framework for identifying AI opportunities", {
    x: 0.6, y: 0.8, w: 8, h: 0.35,
    fontSize: 11, fontFace: FONT_BODY, color: C.textMuted,
    align: "left", margin: 0
  });

  // Agent type headers (columns)
  const agentTypes = [
    { name: "Customer", color: C.accent },
    { name: "Employee", color: C.accentGreen },
    { name: "Creative", color: C.accentYellow },
    { name: "Code", color: "9B59B6" },
    { name: "Data", color: C.accentRed },
    { name: "Security", color: "1ABC9C" },
  ];
  const gridStartX = 2.6;
  const gridStartY = 1.35;
  const colW = 1.2;
  const rowH = 0.32;
  const labelW = 2.0;

  // Column headers
  agentTypes.forEach((agent, i) => {
    const cx = gridStartX + i * colW;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: gridStartY, w: colW - 0.05, h: 0.38,
      fill: { color: agent.color },
    });
    slide.addText(agent.name, {
      x: cx, y: gridStartY, w: colW - 0.05, h: 0.38,
      fontSize: 10, fontFace: FONT_BODY, color: C.white,
      bold: true, align: "center", valign: "middle", margin: 0
    });
  });

  // Industry rows
  const industries = [
    "Automotive & Logistics",
    "Business & Professional Svcs",
    "Financial Services",
    "Healthcare & Life Sciences",
    "Hospitality & Travel",
    "Mfg, Industrial & Electronics",
    "Media, Marketing & Gaming",
    "Public Sector & Nonprofits",
    "Retail",
    "Technology",
    "Telecommunications",
  ];

  industries.forEach((ind, ri) => {
    const ry = gridStartY + 0.45 + ri * (rowH + 0.04);
    const isEven = ri % 2 === 0;

    // Row background
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.6, y: ry, w: labelW + colW * 6 + 0.1, h: rowH,
