    "Healthcare & Life Sciences",
    "Hospitality & Travel",
    "Mfg, Industrial & Electronics",
    "Media, Marketing & Gaming",
    "Public Sector & Nonprofits",
    "Retail",
    "Technology",
    "Telecommunications",
  ];

  industries.forEach((ind, ri) => {
    const ry = gridStartY + 0.45 + ri * (rowH + 0.04);
