      x: 0.65, y: ry, w: labelW - 0.1, h: rowH,
      fontSize: 9, fontFace: FONT_BODY, color: C.textLight,
      align: "left", valign: "middle", margin: 0
    });

    // Dot indicators (filled circles for the grid)
    agentTypes.forEach((agent, ci) => {
      const cx = gridStartX + ci * colW + (colW - 0.05) / 2 - 0.06;
      slide.addShape(pres.shapes.OVAL, {
        x: cx, y: ry + rowH/2 - 0.06, w: 0.12, h: 0.12,
        fill: { color: agent.color, transparency: 25 },
      });
    });
  });

  // Footer note
  slide.addText("Each dot represents active use cases within that industry-agent intersection. All 11 industries deploy Customer and Employee agents.", {
    x: 0.6, y: 5.1, w: 8.8, h: 0.35,
    fontSize: 9, fontFace: FONT_BODY, color: C.textMuted,
    align: "left", margin: 0
  });
}

